pub fn median(_values: &[i64]) -> Option<f64> {
    let mut sorted_values: Vec<i64> = _values.iter().copied().collect();
    sorted_values.sort();

    let n: usize = sorted_values.len();
    if n == 0 {
        return None;
    }

    if n % 2 == 1 {
        let mid: usize = n / 2;
        return Some(sorted_values[mid].as_f64());
    } else {
        let mid1: usize = n / 2 - 1;
        let mid2: usize = mid1 + 1;
        let mid1_val: i64 = sorted_values[mid1];
        let mid2_val: i64 = sorted_values[mid2];
        return Some((mid1_val as f64 + mid2_val as f64) / 2.0);
    }
}

